"""``scripts/test_bundles.py`` runs each bundle in a locked environment of its own, in parallel.

Every test here drives the runner, unmodified, from a copy in a planted tree: planted bundles, a
lock generated by ``scripts/bundle_lock.py`` against a local index of planted packages, and a stub
core (``planted_envs``). Nothing reaches the network, and no real bundle suite runs.

The planted controls, one each:

- selection: ``--changed`` picks exactly the touched bundle; every path that can change any
  bundle's run selects every bundle, and so does an unknown base, a shallow clone and a git error;
  a change no bundle reads selects none;
- isolation: two bundles that declare different packages each see only their own, and a bundle
  that declares none sees neither;
- ``--jobs 2`` names a failing bundle and exits 1;
- the key changes with each of its inputs (core, dependency set, Python version, ABI, OS,
  architecture, uv version, index, resolution), and the live inputs are the host's own;
- two runs building one environment at once give one build and one reuse;
- a build killed part way is discarded and rebuilt, as are an environment whose receipt is
  incomplete and one whose interpreter is gone;
- a bundle whose declared packages the lock does not hold, and a package the lock holds without a
  hash, are refused before anything is installed;
- a bundle whose test changes its environment fails the run, by name;
- every environment's own folder is named ``.venv``;
- a rename is read as both its paths: a file moved out of a shared path selects every bundle, and
  one moved between bundles, committed or only staged, selects both;
- a full run that finds no tested bundle, and ``--changed`` falling back to every bundle when
  there is none, exit 2;
- an environment that changed since it was built, or whose interpreter is no longer the Python
  its key names, is built again rather than reused;
- under ``--jobs``, only the bundle that changed a shared environment is named; a bundle's own
  first failure stands after it passes alone, and so does its first JUnit; a change that no
  bundle makes alone fails every bundle that saw it; a run stopped while it settles records no
  suspect as passed, and names the bundle it is about to run alone;
- one checkout runs one runner: a second refuses and names the first, and the checkout stays held
  while a killed runner's pytest runs on;
- a bundle named twice runs once;
- a build that fails leaves no temporary folder, and each run sweeps the ones a stopped build left
  and environments no run has used for a week, but never one a run holds, one a build used after
  the sweep read its age, or a folder the runner did not name, and it lists only what went;
- a hung bundle is named when it starts, and a hung build names the bundles waiting on it;
- a lock whose extra lost its edges is refused, naming the bundle;
- a locked run refuses a core other than core.lock's; only ``--float`` takes another;
- the floating resolution is the canary's alone: ``ci.yml`` never passes ``--float``.
"""

from __future__ import annotations

import argparse
import fcntl
import json
import os
import platform
import shutil
import signal
import subprocess
import sys
import time
from pathlib import Path

import pytest
import yaml

import planted_envs as planted

ROOT = Path(__file__).resolve().parents[2]
RUNNER = ROOT / "scripts" / "test_bundles.py"

IMPORTS_ONLY = """\
import importlib.util

def test_sees_only_what_it_declares():
    seen = {{name for name in ("dep_alpha", "dep_beta") if importlib.util.find_spec(name)}}
    assert seen == {expected!r}
"""


@pytest.fixture
def world(tmp_path):
    """A planted tree, an index holding dep-alpha and dep-beta, and a stub core."""
    root = planted.tree(tmp_path)
    index = planted.Index(tmp_path / "index")
    index.add("dep-alpha")
    index.add("dep-beta")
    core = planted.stub_core(tmp_path / "core")
    return root, index, core


def _results(root: Path, name: str = "out") -> dict:
    return json.loads((root / name / "results.json").read_text(encoding="utf-8"))


def _run(root, lock_dir, core, *args, **kw):
    return planted.runner(root, lock_dir, core, *args, **kw)


# -- isolation --------------------------------------------------------------------------------

def test_each_bundle_sees_only_the_packages_it_declares(world):
    root, index, core = world
    planted.bundle(root, "alpha-app", deps=["dep-alpha>=1"],
                   tests={"test_sees.py": IMPORTS_ONLY.format(expected={"dep_alpha"})})
    planted.bundle(root, "beta-app", deps=["dep-beta>=1"],
                   tests={"test_sees.py": IMPORTS_ONLY.format(expected={"dep_beta"})})
    planted.bundle(root, "plain-app", tests={"test_sees.py": IMPORTS_ONLY.format(expected=set())})
    lock_dir = planted.lock(root, index)
    run = _run(root, lock_dir, core, "--jobs", "1", "--results", "out")
    assert run.returncode == 0, run.stdout + run.stderr
    assert "OK: 3 bundle(s) passed" in run.stdout
    keys = {b["bundle"]: b["environment"] for b in _results(root)["bundles"]}
    assert len(set(keys.values())) == 3, keys


def test_bundles_that_declare_the_same_packages_share_one_environment(world):
    root, index, core = world
    for name in ("one-app", "two-app"):
        planted.bundle(root, name, deps=["dep-alpha>=1"])
    run = _run(root, planted.lock(root, index), core, "--results", "out")
    assert run.returncode == 0, run.stdout + run.stderr
    results = _results(root)
    assert len({b["environment"] for b in results["bundles"]}) == 1
    assert [e["action"] for e in results["environments"]] == ["built"]


def test_the_declared_dependency_is_absent_without_the_runner_and_present_with_it(world, tmp_path):
    # The runner's first test, kept: the planted bundle's import fails in an environment that does
    # not hold its declared package, and passes when the runner builds the bundle's environment.
    root, index, core = world
    app = planted.bundle(root, "needs-alpha", deps=["dep-alpha>=1"],
                         tests={"test_import.py": "from dep_alpha import VALUE\n\n"
                                                  "def test_value():\n    assert VALUE == 1\n"})
    bare = tmp_path / "bare" / ".venv"
    subprocess.run(["uv", "venv", "-q", "--no-config", "--python", sys.executable, str(bare)],
                   check=True)
    runner = planted.load(root / "scripts" / "test_bundles.py", "_planted_runner")
    without = runner.run_pytest(app, python=str(bare / "bin" / "python"), env=planted.environ())
    assert without.returncode != 0
    assert "No module named 'dep_alpha'" in without.output
    run = _run(root, planted.lock(root, index), core)
    assert run.returncode == 0, run.stdout + run.stderr


# -- parallel runs ----------------------------------------------------------------------------

def test_jobs_names_a_failing_bundle_and_exits_one(world):
    root, index, core = world
    planted.bundle(root, "good-app")
    planted.bundle(root, "bad-app", tests={"test_bad.py": "def test_bad():\n    assert False\n"})
    run = _run(root, planted.lock(root, index), core, "--jobs", "2", "--results", "out")
    assert run.returncode == 1, run.stdout + run.stderr
    assert "FAILED bundles: bad-app" in run.stderr
    assert {b["bundle"]: b["returncode"] != 0 for b in _results(root)["bundles"]} == {
        "bad-app": True, "good-app": False}


def test_each_bundle_s_output_is_one_block(world):
    root, index, core = world
    for name in ("first-app", "second-app"):
        planted.bundle(root, name, tests={
            "test_says.py": f"def test_says():\n    print('said by {name}')\n    assert False\n"})
    run = _run(root, planted.lock(root, index), core, "--jobs", "2")
    blocks = run.stdout.split("\n=== ")[1:]
    assert sorted(b.split(" ", 1)[0].strip() for b in blocks) == ["first-app", "second-app"]
    for block in blocks:
        name = block.split(" ", 1)[0].strip()
        other = "second-app" if name == "first-app" else "first-app"
        assert f"said by {name}" in block and f"said by {other}" not in block


def test_the_default_jobs_is_half_the_cpus_at_most_eight():
    runner = planted.load(RUNNER, "_real_runner")
    assert runner.default_jobs() == max(1, min(8, (os.cpu_count() or 2) // 2))


# -- the environment key ------------------------------------------------------------------------

KEY_INPUTS = {
    "core": "a" * 40, "requirements": "b" * 64, "python": "3.12.15",
    "abi": "cpython-312-x86_64-linux-gnu", "os": "Linux glibc 2.39", "arch": "x86_64",
    "uv": "0.13.1", "index": "https://pypi.org/simple", "resolution": "locked",
}


@pytest.mark.parametrize("field,other", [
    ("core", "c" * 40), ("requirements", "d" * 64), ("python", "3.12.16"),
    ("abi", "cpython-313-x86_64-linux-gnu"), ("os", "Darwin 15.5"), ("arch", "arm64"),
    ("uv", "0.13.2"), ("index", "https://index.example.com/simple"), ("resolution", "floating"),
])
def test_the_key_changes_with_each_of_its_inputs(field, other):
    runner = planted.load(RUNNER, "_real_runner")
    assert set(KEY_INPUTS) == set(runner.KEY_FIELDS)
    assert runner.environment_key(KEY_INPUTS) == runner.environment_key(dict(KEY_INPUTS))
    assert runner.environment_key({**KEY_INPUTS, field: other}) != runner.environment_key(KEY_INPUTS)


def test_the_live_key_inputs_are_this_host_s_own():
    # The vacuity floor: a key that read constants would pass every row above.
    runner = planted.load(RUNNER, "_real_runner")
    host = runner.host_inputs(sys.executable)
    assert host["python"] == platform.python_version()
    assert host["arch"] == platform.machine()
    assert host["os"].startswith(platform.system())
    assert sys.implementation.cache_tag.split("-")[1] in host["abi"]
    uv = subprocess.run(["uv", "--version"], capture_output=True, text=True, check=True).stdout
    assert host["uv"] == uv.split()[1]


#: What ci.yml and core-main-canary.yml set for every step. Every other planted run here names the
#: interpreter itself, which skips the lookup these two rows exercise.
WORKFLOW_ENV = {"UV_PYTHON_PREFERENCE": "only-managed"}


@pytest.mark.parametrize("preference", [None, "only-managed", "managed", "system", ""],
                         ids=["unset", "only-managed", "managed", "system", "empty"])
def test_the_interpreter_lookup_finds_the_pinned_python_whatever_uv_s_preference(
        monkeypatch, preference):
    # The first CI run failed here: `uv python find --managed-python` refuses to run beside the
    # workflow's UV_PYTHON_PREFERENCE, and every planted run set BUNDLE_RUNNER_ENV_PYTHON.
    runner = planted.load(RUNNER, "_real_runner")
    bundle_lock = planted.load(ROOT / "scripts" / "bundle_lock.py", "_real_bundle_lock")
    monkeypatch.delenv("BUNDLE_RUNNER_ENV_PYTHON", raising=False)
    monkeypatch.delenv("UV_MANAGED_PYTHON", raising=False)
    if preference is None:
        monkeypatch.delenv("UV_PYTHON_PREFERENCE", raising=False)
    else:
        monkeypatch.setenv("UV_PYTHON_PREFERENCE", preference)
    python = runner.env_python(bundle_lock)
    version = subprocess.run([python, "-c", "import platform; print(platform.python_version())"],
                             capture_output=True, text=True, check=True).stdout.strip()
    assert version == bundle_lock.PYTHON


def test_a_planted_run_that_names_no_interpreter_builds_from_the_pinned_python(world):
    # The real lookup, under the workflow's own environment, end to end: the environment's
    # interpreter is uv's managed copy of the pinned Python, not the one running the runner.
    root, index, core = world
    bundle_lock = planted.load(root / "scripts" / "bundle_lock.py", "_planted_bundle_lock")
    planted.bundle(root, "pinned-app", deps=["dep-alpha>=1"], tests={
        "test_pinned.py": "import platform\n\ndef test_pinned():\n"
                          f"    assert platform.python_version() == {bundle_lock.PYTHON!r}\n"})
    lock_dir = planted.lock(root, index, python=bundle_lock.PYTHON)
    env = {**planted.environ(lock_dir, core, root / ".bundle-venvs"), **WORKFLOW_ENV}
    env.pop("BUNDLE_RUNNER_ENV_PYTHON")
    run = subprocess.run([sys.executable, str(root / "scripts" / "test_bundles.py"),
                          "--results", "out"], cwd=root, env=env, capture_output=True, text=True)
    assert run.returncode == 0, run.stdout + run.stderr
    (environment,) = _results(root)["environments"]
    assert environment["inputs"]["python"] == bundle_lock.PYTHON


def test_the_core_in_the_key_is_the_commit_core_lock_pins(tmp_path):
    root = planted.tree(tmp_path)
    runner = planted.load(root / "scripts" / "test_bundles.py", "_planted_runner")
    (root / "core.lock").write_text("a" * 40 + "\n", encoding="utf-8")
    first = runner.core_identity(root, override=None)
    (root / "core.lock").write_text("b" * 40 + "\n", encoding="utf-8")
    assert (first, runner.core_identity(root, override=None)) == ("a" * 40, "b" * 40)


def test_a_changed_dependency_list_yields_a_new_key(world):
    root, index, core = world
    planted.bundle(root, "moving-app", deps=["dep-alpha>=1"])
    assert _run(root, planted.lock(root, index), core, "--results", "out").returncode == 0
    before = _results(root)["bundles"][0]["environment"]
    planted.bundle(root, "moving-app", deps=["dep-alpha>=1", "dep-beta>=1"])
    assert _run(root, planted.lock(root, index), core, "--results", "out").returncode == 0
    assert _results(root)["bundles"][0]["environment"] != before


# -- building an environment ------------------------------------------------------------------

def test_a_build_killed_part_way_is_discarded_and_rebuilt(world):
    root, index, core = world
    planted.bundle(root, "killed-app", deps=["dep-alpha>=1"])
    lock_dir = planted.lock(root, index)
    envs = root / ".bundle-venvs"
    env = planted.environ(lock_dir, core, envs, BUNDLE_RUNNER_BUILD_PAUSE="30")
    proc = subprocess.Popen([sys.executable, str(root / "scripts" / "test_bundles.py")], cwd=root,
                            env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                            start_new_session=True)
    deadline = time.monotonic() + 60
    while not list(envs.glob(".tmp-*/.venv/bin/python")) and time.monotonic() < deadline:
        time.sleep(0.05)
    os.killpg(proc.pid, signal.SIGKILL)
    proc.wait()
    assert list(envs.glob(".tmp-*")), "the build was not caught part way"
    assert not [p for p in envs.iterdir() if p.is_dir() and not p.name.startswith(".")]
    run = _run(root, lock_dir, core, "--results", "out")
    assert run.returncode == 0, run.stdout + run.stderr
    assert _results(root)["environments"][0]["action"] == "built"
    assert not list(envs.glob(".tmp-*"))


@pytest.mark.parametrize("damage", ["incomplete receipt", "interpreter gone"])
def test_a_damaged_environment_is_discarded_and_rebuilt(world, damage):
    root, index, core = world
    planted.bundle(root, "damaged-app", deps=["dep-alpha>=1"])
    lock_dir = planted.lock(root, index)
    assert _run(root, lock_dir, core).returncode == 0
    (final,) = [p for p in (root / ".bundle-venvs").iterdir()
                if p.is_dir() and not p.name.startswith(".")]
    if damage == "incomplete receipt":
        receipt = json.loads((final / "environment.json").read_text())
        (final / "environment.json").write_text(json.dumps({**receipt, "complete": False}))
    else:
        shutil.rmtree(final / ".venv" / "bin")
    run = _run(root, lock_dir, core, "--results", "out")
    assert run.returncode == 0, run.stdout + run.stderr
    assert _results(root)["environments"][0]["action"] == "built"


def test_every_environment_s_own_folder_is_named_venv(world):
    root, index, core = world
    planted.bundle(root, "named-app", deps=["dep-beta>=1"])
    planted.bundle(root, "bare-app")
    assert _run(root, planted.lock(root, index), core, "--results", "out").returncode == 0
    environments = _results(root)["environments"]
    assert len(environments) == 2
    for environment in environments:
        assert Path(environment["python"]).parent.parent.name == ".venv", environment


def test_the_runner_waits_for_the_environment_lock_before_it_builds(world):
    root, index, core = world
    planted.bundle(root, "locked-app", deps=["dep-alpha>=1"])
    lock_dir = planted.lock(root, index)
    assert _run(root, lock_dir, core, "--results", "out").returncode == 0
    key = _results(root)["environments"][0]["key"]
    envs = root / ".bundle-venvs"
    with open(envs / f"{key}.lock", "a") as held:
        fcntl.flock(held, fcntl.LOCK_EX)
        shutil.rmtree(envs / key)
        proc = subprocess.Popen([sys.executable, str(root / "scripts" / "test_bundles.py")],
                                cwd=root, env=planted.environ(lock_dir, core, envs),
                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        time.sleep(1.5)
        assert proc.poll() is None and not (envs / key).exists()
    assert proc.wait(timeout=60) == 0


# -- what the lock must hold ------------------------------------------------------------------

def test_a_bundle_whose_declared_packages_the_lock_does_not_hold_is_refused(world):
    root, index, core = world
    planted.bundle(root, "drifted-app", deps=["dep-alpha>=1"])
    lock_dir = planted.lock(root, index)
    planted.bundle(root, "drifted-app", deps=["dep-alpha>=1", "dep-beta>=1"])
    run = _run(root, lock_dir, core)
    assert run.returncode == 2, run.stdout + run.stderr
    assert "drifted-app" in run.stderr and "scripts/bundle_lock.py" in run.stderr
    envs = root / ".bundle-venvs"
    assert not envs.exists() or not [p for p in envs.iterdir() if p.is_dir()]


def test_a_package_the_lock_holds_without_a_hash_is_refused(world):
    root, index, core = world
    index.add("dep-unhashed", hashed=False)
    planted.bundle(root, "unhashed-app", deps=["dep-unhashed>=1"])
    run = _run(root, planted.lock(root, index), core)
    assert run.returncode == 2, run.stdout + run.stderr
    assert "dep-unhashed" in run.stderr and "hash" in run.stderr


def test_a_bundle_whose_test_installs_a_package_fails_the_run_by_name(world):
    root, index, core = world
    index.add("dep-gamma")
    installs = (
        "import subprocess, sys\n\n"
        "def test_installs():\n"
        "    subprocess.run(['uv', 'pip', 'install', '-q', '--no-config', '--python', sys.executable,\n"
        f"                    '--default-index', {index.url!r}, 'dep-gamma'], check=True)\n"
    )
    planted.bundle(root, "installer-app", tests={"test_installs.py": installs})
    planted.bundle(root, "quiet-app", deps=["dep-alpha>=1"])
    run = _run(root, planted.lock(root, index), core, "--jobs", "1", "--results", "out")
    assert run.returncode == 1, run.stdout + run.stderr
    assert "installer-app" in run.stderr and "changed its environment" in run.stderr
    assert "dep-gamma" in run.stderr
    rows = {b["bundle"]: b["returncode"] for b in _results(root)["bundles"]}
    assert rows["installer-app"] != 0 and rows["quiet-app"] == 0


# -- selection --------------------------------------------------------------------------------

@pytest.fixture
def repo(tmp_path):
    """A committed planted tree with two bundles; returns it and the base commit."""
    root = planted.tree(tmp_path)
    for name in ("first-app", "second-app"):
        planted.bundle(root, name)
    (root / "docs").mkdir()
    (root / "docs" / "guide.md").write_text("guide\n", encoding="utf-8")
    planted.git(root, "init", "-q")
    return root, planted.commit(root, "base")


def _selected(root: Path, base: str) -> tuple[list[str], str]:
    run = subprocess.run([sys.executable, str(root / "scripts" / "test_bundles.py"), "--list",
                          "--changed", base], cwd=root, capture_output=True, text=True,
                         env=planted.environ())
    assert run.returncode == 0, run.stdout + run.stderr
    lines = run.stdout.splitlines()
    reason = next(line for line in lines if line.startswith("selection: "))
    return [line for line in lines if line and not line.startswith("selection: ")], reason


def test_changed_selects_exactly_the_touched_bundle(repo):
    root, base = repo
    (root / "first-app" / "provider.py").write_text("X = 1\n", encoding="utf-8")
    planted.commit(root)
    assert _selected(root, base)[0] == ["first-app"]


def test_changed_also_reads_the_uncommitted_work_tree(repo):
    root, base = repo
    (root / "second-app" / "provider.py").write_text("X = 1\n", encoding="utf-8")
    assert _selected(root, base)[0] == ["second-app"]


@pytest.mark.parametrize("path", [
    "core.lock", "apps_testkit/helper.py", "scripts/helper.py", "conftest.py", "pytest.ini",
    ".github/tests/test_more.py", ".github/bundle-lock/linux-x86_64/uv.lock",
    ".github/workflows/ci.yml", ".nvmrc", "tox.ini",
])
def test_changed_selects_every_bundle_when_a_shared_path_changes(repo, path):
    root, base = repo
    target = root / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("changed\n", encoding="utf-8")
    planted.commit(root)
    bundles, reason = _selected(root, base)
    assert bundles == ["first-app", "second-app"] and path in reason


def test_changed_selects_no_bundle_when_only_docs_change(repo):
    root, base = repo
    (root / "docs" / "guide.md").write_text("guide, reworded\n", encoding="utf-8")
    (root / "README.md").write_text("readme\n", encoding="utf-8")
    planted.commit(root)
    bundles, reason = _selected(root, base)
    assert bundles == [] and "no bundle" in reason


@pytest.mark.parametrize("source,destination,expected", [
    ("apps_testkit/helper.py", "first-app/helper.py", ["first-app", "second-app"]),
    ("conftest.py", "docs/conftest.py", ["first-app", "second-app"]),
    ("first-app/NOTE.md", "docs/note.md", ["first-app"]),
    ("first-app/helper.py", "second-app/helper.py", ["first-app", "second-app"]),
])
@pytest.mark.parametrize("committed", [True, False], ids=["committed", "staged"])
def test_a_rename_selects_by_both_its_paths(repo, source, destination, expected, committed):
    root, _ = repo
    (root / source).parent.mkdir(parents=True, exist_ok=True)
    (root / source).write_text("moved, unchanged\n", encoding="utf-8")
    base = planted.commit(root, "the file to move")
    (root / destination).parent.mkdir(parents=True, exist_ok=True)
    planted.git(root, "mv", source, destination)
    if committed:
        planted.commit(root, "moved")
    bundles, reason = _selected(root, base)
    assert bundles == expected, reason
    if not source.split("/")[0].endswith("-app"):
        # A shared source selects every bundle, and the reason names it.
        assert source in reason, reason


def test_a_deleted_bundle_has_nothing_to_run(repo):
    root, base = repo
    shutil.rmtree(root / "second-app")
    planted.commit(root)
    bundles, reason = _selected(root, base)
    assert bundles == [] and "second-app" in reason


def test_changed_selects_every_bundle_for_an_unknown_base(repo):
    root, _ = repo
    bundles, reason = _selected(root, "0" * 40)
    assert bundles == ["first-app", "second-app"] and "unknown base" in reason


def test_changed_selects_every_bundle_for_no_base(repo):
    root, _ = repo
    bundles, reason = _selected(root, "")
    assert bundles == ["first-app", "second-app"] and "no base" in reason


def test_changed_selects_every_bundle_in_a_shallow_clone(repo, tmp_path):
    root, base = repo
    (root / "first-app" / "provider.py").write_text("X = 1\n", encoding="utf-8")
    planted.commit(root)
    shallow = tmp_path / "shallow"
    subprocess.run(["git", "clone", "-q", "--depth", "1", root.as_uri(), str(shallow)], check=True)
    bundles, reason = _selected(shallow, base)
    assert bundles == ["first-app", "second-app"] and "shallow" in reason


def test_changed_selects_every_bundle_when_git_cannot_read_the_diff(repo, tmp_path):
    root, base = repo
    copy = tmp_path / "not-a-checkout"
    shutil.copytree(root, copy, ignore=shutil.ignore_patterns(".git"))
    bundles, reason = _selected(copy, base)
    assert bundles == ["first-app", "second-app"] and "git" in reason


def test_a_run_with_no_bundle_selected_passes_and_says_why(repo):
    root, base = repo
    (root / "docs" / "guide.md").write_text("guide, again\n", encoding="utf-8")
