def test_an_environment_whose_interpreter_moved_to_another_patch_is_built_again(world):
    # uv links an environment through its minor-version folder; a patch upgrade re-points it.
    # Planted: the environment's python reports another patch, everything else unchanged.
    root, index, core = world
    planted.bundle(root, "drifted-python-app")
    lock_dir = planted.lock(root, index)
    assert _run(root, lock_dir, core).returncode == 0
    (final,) = _envs(root)
    bin_dir = final / ".venv" / "bin"
    os.rename(bin_dir / "python", bin_dir / "python-real")
    drift = final / "drift"
    drift.mkdir()
    (drift / "sitecustomize.py").write_text(
        "import platform\nplatform.python_version = lambda: '3.0.1'\n", encoding="utf-8")
    (bin_dir / "python").write_text(
        f'#!/bin/sh\nPYTHONPATH="{drift}${{PYTHONPATH:+:$PYTHONPATH}}" '
        'exec "$(dirname "$0")/python-real" "$@"\n', encoding="utf-8")
    (bin_dir / "python").chmod(0o755)
    run = _run(root, lock_dir, core, "--results", "out")
    assert run.returncode == 0, run.stdout + run.stderr
    assert _results(root)["environments"][0]["action"] == "built"


# Bundles that meet through marker files rather than sleeps: the installer installs once its peer
# has started, and the peer ends once the install has landed. Run alone, each finds its marker
# already there and goes straight on, so a settled run costs no waiting.
_WAIT = (
    "import pathlib, subprocess, sys, time\n\n"
    "def _until(path):\n"
    "    deadline = time.monotonic() + 30\n"
    "    while not pathlib.Path(path).exists() and time.monotonic() < deadline:\n"
    "        time.sleep(0.02)\n\n"
    "def _uv(*argv):\n"
    "    subprocess.run(['uv', 'pip', *argv[:1], '-q', '--no-config', '--python', sys.executable,\n"
    "                    *argv[1:]], check=True)\n\n"
)
INSTALLS_ONCE_ITS_PEER_STARTED = _WAIT + (
    "def test_installs():\n"
    "    _until({started!r})\n"
    "    _uv('install', '--default-index', {url!r}, 'dep-gamma')\n"
    "    pathlib.Path({installed!r}).touch()\n"
)
INSTALLS_THEN_REMOVES = _WAIT + (
    "def test_installs_then_removes():\n"
    "    _until({started!r})\n"
    "    _uv('install', '--default-index', {url!r}, 'dep-gamma')\n"
    "    pathlib.Path({installed!r}).touch()\n"
    "    _until({done!r})\n"
    "    time.sleep(2)  # the runner's after-snapshot of the peer, taken once its pytest exits\n"
    "    _uv('uninstall', 'dep-gamma')\n"
)
PEER = _WAIT + (
    "def test_peer():\n"
    "    pathlib.Path({started!r}).touch()\n"
    "    _until({installed!r})\n"
    "    pathlib.Path({done!r}).touch()\n"
)
FAILS_THE_FIRST_TIME = PEER.replace("def test_peer():\n", "def test_peer():\n"
    "    runs = pathlib.Path({runs!r})\n"
    "    seen = runs.exists()\n"
    "    runs.touch()\n") + "    assert seen, 'fails the first time it runs'\n"


def _pair(root, tmp_path, index, installer, peer, *, peer_name="innocent-app", **extra):
    """The installer and a peer in the base environment, meeting through markers in tmp_path."""
    marks = {n: str(tmp_path / n) for n in ("started", "installed", "done", "runs")}
    planted.bundle(root, "installer-app",
                   tests={"test_installs.py": installer.format(url=index.url, **marks)})
    planted.bundle(root, peer_name, tests={"test_peer.py": peer.format(**marks)})
    return marks


def test_under_jobs_only_the_bundle_that_changed_a_shared_environment_is_named(world, tmp_path):
    root, index, core = world
    index.add("dep-gamma")
    _pair(root, tmp_path, index, INSTALLS_ONCE_ITS_PEER_STARTED, PEER)
    run = _run(root, planted.lock(root, index), core, "--jobs", "2", "--results", "out")
    assert run.returncode == 1, run.stdout + run.stderr
    assert "running each alone" in run.stderr, run.stderr  # the shared path, not one at a time
    assert "installer-app changed its environment" in run.stderr
    assert "innocent-app changed its environment" not in run.stderr
    assert "FAILED bundles: installer-app\n" in run.stderr
    rows = {b["bundle"]: b["returncode"] for b in _results(root)["bundles"]}
    assert rows["installer-app"] != 0 and rows["innocent-app"] == 0, rows


def test_under_jobs_a_bundle_s_own_first_failure_stands_after_it_passes_alone(world, tmp_path):
    # The runs alone only find the culprit: a bundle that failed beside it stays failed, and its
    # first run's JUnit stays, with the run alone's beside it.
    root, index, core = world
    index.add("dep-gamma")
    _pair(root, tmp_path, index, INSTALLS_ONCE_ITS_PEER_STARTED, FAILS_THE_FIRST_TIME,
          peer_name="flaky-app")
    run = _run(root, planted.lock(root, index), core, "--jobs", "2", "--results", "out")
    assert run.returncode == 1, run.stdout + run.stderr
    assert "1 passed" in run.stdout.split("=== flaky-app (alone) ===")[1], run.stdout
    assert "flaky-app changed its environment" not in run.stderr
    assert "FAILED bundles: flaky-app, installer-app\n" in run.stderr, run.stderr
    rows = {b["bundle"]: b for b in _results(root)["bundles"]}
    assert rows["flaky-app"]["returncode"] != 0, rows
    assert 'failures="1"' in (root / "out" / rows["flaky-app"]["junit"]).read_text()
    assert 'failures="0"' in (root / "out" / "alone" / rows["flaky-app"]["junit"]).read_text()


def test_under_jobs_a_change_no_bundle_makes_alone_fails_every_bundle_that_saw_it(world, tmp_path):
    # The installer removes what it installed inside its own window, so only the peer sees the
    # change, and run alone neither changes the environment: the run cannot name one, so neither
    # passes.
    root, index, core = world
    index.add("dep-gamma")
    _pair(root, tmp_path, index, INSTALLS_THEN_REMOVES, PEER)
    run = _run(root, planted.lock(root, index), core, "--jobs", "2", "--results", "out")
    assert run.returncode == 1, run.stdout + run.stderr
    assert "none of them changes it when run alone" in run.stderr, run.stderr
    assert "FAILED bundles: innocent-app, installer-app\n" in run.stderr
    rows = {b["bundle"]: b["returncode"] for b in _results(root)["bundles"]}
    assert rows["installer-app"] != 0 and rows["innocent-app"] != 0, rows


def _until(done, seconds: float = 60) -> bool:
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline and not done():
        time.sleep(0.05)
    return done()


def test_a_run_stopped_while_settling_shows_no_suspect_passed_and_names_the_bundle_alone(
        world, tmp_path):
    root, index, core = world
    index.add("dep-gamma")
    _pair(root, tmp_path, index, INSTALLS_ONCE_ITS_PEER_STARTED, PEER)
    hold = tmp_path / "hold-the-rebuild"
    hold.touch()
    log = tmp_path / "stderr.log"
    with open(log, "w") as err:
        proc = subprocess.Popen(
            [sys.executable, str(root / "scripts" / "test_bundles.py"), "--jobs", "2",
             "--results", "out"], cwd=root, stdout=subprocess.DEVNULL, stderr=err,
            env=planted.environ(planted.lock(root, index), core, root / ".bundle-venvs",
                                BUNDLE_RUNNER_REBUILD_HOLD=str(hold)))
    try:
        assert _until(lambda: "running each alone" in log.read_text()), log.read_text()
        rows = {b["bundle"]: b["returncode"] for b in _results(root)["bundles"]}
        assert set(rows) == {"installer-app", "innocent-app"} and all(rows.values()), rows
        # Its rebuild is held: the log names the bundle waiting to run alone.
        assert "innocent-app (alone): started" in log.read_text()
        assert "=== innocent-app (alone) ===" not in log.read_text() and proc.poll() is None
    finally:
        hold.unlink()
    assert proc.wait(timeout=60) == 1
    rows = {b["bundle"]: b["returncode"] for b in _results(root)["bundles"]}
    assert rows["installer-app"] != 0 and rows["innocent-app"] == 0, rows


