WAITS_FOR_RELEASE = (
    "import pathlib, time\n\n"
    "def test_waits():\n"
    "    pathlib.Path({started!r}).touch()\n"
    "    deadline = time.monotonic() + 60\n"
    "    while not pathlib.Path({release!r}).exists() and time.monotonic() < deadline:\n"
    "        time.sleep(0.02)\n"
)


def _holding_run(root, tmp_path, index, core, **popen):
    started, release = tmp_path / "started", tmp_path / "release"
    planted.bundle(root, "holder-app", tests={
        "test_waits.py": WAITS_FOR_RELEASE.format(started=str(started), release=str(release))})
    lock_dir = planted.lock(root, index)
    proc = subprocess.Popen([sys.executable, str(root / "scripts" / "test_bundles.py")], cwd=root,
                            env=planted.environ(lock_dir, core, root / ".bundle-venvs"),
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, **popen)
    assert _until(started.exists), "the holding run never started its bundle"
    return proc, lock_dir, release


def test_a_second_runner_in_the_same_checkout_refuses_and_names_the_first(world, tmp_path):
    root, index, core = world
