def test_the_sweep_keeps_an_environment_a_build_used_after_it_read_the_age(tmp_path, monkeypatch):
    # A build reuses the environment after the sweep read its age and before it took the lock:
    # the sweep reads the age again under the lock and keeps it.
    runner = planted.load(RUNNER, "_real_runner_sweep")
    envs = tmp_path / ".bundle-venvs"
    final = envs / ("a" * 32)
    (final / ".venv").mkdir(parents=True)
    stamp = final / "environment.json"
    stamp.write_text("{}", encoding="utf-8")
    week_ago = time.time() - 8 * 24 * 3600
    os.utime(stamp, (week_ago, week_ago))
    key_lock = runner._key_lock

    def used_meanwhile(key):
        if key == final.name:
            os.utime(stamp)
        return key_lock(key)

    monkeypatch.setattr(runner, "_key_lock", used_meanwhile)
    assert runner.sweep(envs, set()) == []
    assert final.exists()


def test_the_sweep_removes_only_folders_the_runner_names_and_names_only_what_went(tmp_path):
    runner = planted.load(RUNNER, "_real_runner_sweep_names")
    envs = tmp_path / ".bundle-venvs"
    week_ago = time.time() - 8 * 24 * 3600

    def folder(path):
        (path / ".venv").mkdir(parents=True)
        (path / "environment.json").write_text("{}", encoding="utf-8")
        os.utime(path / "environment.json", (week_ago, week_ago))
        os.utime(path, (week_ago, week_ago))
        return path

    stale = folder(envs / ("f" * 32))
    notes, scratch = folder(envs / "notes"), folder(envs / ".tmp-scratch")
    elsewhere = folder(tmp_path / "elsewhere")
    linked = envs / ("a" * 32)
    linked.symlink_to(elsewhere, target_is_directory=True)
    stuck = folder(envs / ("b" * 32))
    sealed = stuck / ".venv" / "sealed"
    sealed.mkdir()
    (sealed / "kept").write_text("", encoding="utf-8")
    sealed.chmod(0o500)
    try:
        swept = runner.sweep(envs, set())
    finally:
        if sealed.exists():
            sealed.chmod(0o700)
    assert notes.exists() and scratch.exists() and (elsewhere / "environment.json").exists()
    assert not (envs / "notes.lock").exists() and not (envs / "scratch.lock").exists()
    assert not stale.exists() and stale.name in swept
    assert linked.name not in swept
    assert [name for name in swept if os.path.lexists(envs / name)] == []


