def test_a_locked_run_refuses_a_core_other_than_the_one_core_lock_pins(tmp_path, monkeypatch):
    # A guard: the refusal held on 65578e0f, but no planted run reached it.
    root = planted.tree(tmp_path)
    (root / "core.lock").write_text("a" * 40 + "\n", encoding="utf-8")
    runner = planted.load(root / "scripts" / "test_bundles.py", "_planted_runner_cores")
    monkeypatch.setattr(runner, "ROOT", root)
    monkeypatch.delenv("BUNDLE_RUNNER_CORE_SPEC", raising=False)

    def cores(commit, floating=False):
        return runner._cores(argparse.Namespace(core_commit=commit, floating=floating))

    core_lock = planted.load(root / "scripts" / "core_lock.py", "_planted_core_lock_spec")
    with pytest.raises(runner.Refusal, match="only --float tests another core"):
        cores("b" * 40)
    with pytest.raises(runner.Refusal, match="only --float tests another core"):
        cores("a" * 39 + "b")  # a near miss: the same prefix, one character off
    locked = ("a" * 40, core_lock.spec("a" * 40))
    assert cores("A" * 12) == cores(None) == locked
    # Both halves: the identity in the key, and the spec that is installed.
    assert cores("b" * 40, floating=True) == ("b" * 40, core_lock.spec("b" * 40))


# -- the floating resolution stays out of merge evidence ---------------------------------------

def float_problems(ci: dict, canary: dict) -> list[str]:
    def runs(wf):
        return [str(s.get("run") or "") for job in (wf.get("jobs") or {}).values()
                for s in job.get("steps") or []]
    problems = [f"ci.yml floats: {r.strip()}" for r in runs(ci) if "--float" in r]
    gates = [r for r in runs(canary) if "scripts/gate.py" in r]
    if not gates or not all("--float" in r for r in gates):
        problems.append("the canary's gate does not float")
    return problems


def _workflow(name: str) -> dict:
    return yaml.safe_load((ROOT / ".github" / "workflows" / name).read_text(encoding="utf-8"))


def test_only_the_canary_resolves_afresh():
    assert float_problems(_workflow("ci.yml"), _workflow("core-main-canary.yml")) == []


def test_a_planted_float_in_ci_and_a_canary_that_stops_floating_are_caught():
    ci = _workflow("ci.yml")
    gate = next(s for s in ci["jobs"]["tests"]["steps"] if "scripts/gate.py" in str(s.get("run")))
    gate["run"] += " --float"
    assert any("ci.yml floats" in p for p in float_problems(ci, _workflow("core-main-canary.yml")))
    canary = _workflow("core-main-canary.yml")
    step = next(s for s in canary["jobs"]["check"]["steps"]
                if "scripts/gate.py" in str(s.get("run")))
    step["run"] = step["run"].replace(" --float", "")
    assert "the canary's gate does not float" in float_problems(_workflow("ci.yml"), canary)


# -- the launcher -----------------------------------------------------------------------------

def test_the_launcher_names_an_interpreter_it_cannot_find(tmp_path):
    # The shell's own "not found" names neither the variable that picks the interpreter nor
    # the setup that provides one, so the launcher says both before it gives up.
    env = os.environ.copy()
    env["PYTHON"] = str(tmp_path / "no-such-python")
    result = subprocess.run(
        ["sh", str(ROOT / "scripts/test-bundles")],
        cwd=ROOT,
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    assert result.returncode == 127
    assert "PYTHON" in result.stderr
    assert "CONTRIBUTING.md" in result.stderr
